#!/usr/bin/env bash
set -euo pipefail
[[ "$EUID" -ne 0 ]] && { echo -e "\033[1;31m[!] Run as root!\033[0m" >&2; exit 1; }

echo -e "\033[1;36m[*] Extracting ACON Panel (English Only)...\033[0m"

# Clean old cache to trigger installation
rm -rf /etc/aconvip/.installed /etc/aconvip/.v35_ready

B64="

"
echo "$B64" | base64 -d > /usr/bin/menu
chmod +x /usr/bin/menu

echo -e "\033[1;33m[*] Starting ACON Setup...\033[0m"
bash /usr/bin/menu

rm -f /root/install.sh
